      metadata: "\u6838\u5FC3\u7CFB\u7EDF\u5B57\u6BB5\u3002\u6807\u9898\u548C\u5929\u6570\u663E\u793A\u5728\u5217\u8868\u548C\u641C\u7D22\u4E2D\u3002\u72B6\u6001\u63A7\u5236\u5BA2\u6237\u53EF\u89C1\u6027\u3002\u6B63\u786E\u8BBE\u7F6E\u8BED\u8A00\u4EE5\u4F7F\u7FFB\u8BD1\u6B63\u5E38\u5DE5\u4F5C\u3002",
      content_data: "\u5BA2\u6237\u5728\u884C\u7A0B\u9875\u9762\u770B\u5230\u7684\u6240\u6709\u5185\u5BB9\u3002\u884C\u7A0B\u540D\u79F0\u662F\u5927\u6807\u9898\uFF0C\u57FA\u7840\u4EF7\u683C\u663E\u793A\u4E3A\u201C\u8D77\u201D\u4EF7\uFF0C\u4EAE\u70B9\u663E\u793A\u4E3A\u56FE\u6807\uFF0C\u5305\u542B/\u4E0D\u5305\u542B\u663E\u793A\u4E3A\u6E05\u5355\u3002",
      hero_image: "\u884C\u7A0B\u9875\u9762\u9876\u90E8\u7684\u5168\u5BBD\u56FE\u7247\u3002\u4F7F\u7528\u201C\u6DFB\u52A0\u5C01\u9762\u56FE\u201D\u6309\u9215\u4ECE\u753B\u5E93\u9009\u62E9\u6216\u4E0A\u4F20\u3002\u5C01\u9762\u56FE\u59CB\u7EC8\u9700\u8981\u660E\u786E\u8BBE\u7F6E\u2014\u4E0D\u81EA\u52A8\u4ECE\u753B\u5ECE\u5217\u8868\u5C55\u53D6\u3002",
      gallery_images: "\u884C\u7A0B\u753B\u5ECE\u7684\u7167\u7247\u5408\u96C6\u3002\u6DFB\u52A0\u56FE\u7247 \u2014 \u6BCF\u5F20\u56FE\u7247\u4E0D\u5F71\u54CD\u5C01\u9762\u56FE\u6216\u5176\u4ED6\u5B57\u6BB5\u3002",
      destination: "\u884C\u7A0B\u9875\u9762\u7684\u76EE\u7684\u5730\u5361\u7247 \u2014 \u540D\u79F0\u548C\u7167\u7247\u3002\u5728\u7F51\u7AD9\u76EE\u7684\u5730\u9875\u9762\u663E\u793A\u8BE5\u884C\u7A0B\u65F6\uFF0C\u8BF7\u52FE\u9009\u201C\u76EE\u7684\u5730\u201D\u3002",
      accommodation: "\u884C\u7A0B\u9875\u9762\u7684\u9152\u5E97\u4E3B\u63A8 \u2014 \u6807\u9898\u3001\u56FE\u7247\u548C\u7B80\u77ED\u63CF\u8FF0\u3002\u52FE\u9009\u201C\u4F4F\u5BBF\u201D\u5C06\u5176\u5C55\u793A\u5728\u5C55\u793A\u533A\u3002",
      site_placement: "\u63A7\u5236\u8BE5\u884C\u7A0B\u5728\u7F51\u7AD9\u4E0A\u7684\u5176\u4ED6\u663E\u793A\u4F4D\u7F6E\u3002\u7CBE\u9009\u884C\u7A0B\u663E\u793A\u5728\u9996\u9875\u7CBE\u9009\u884C\uFF0C\u76EE\u7684\u5730\u6DFB\u52A0\u5230\u76EE\u5F55\u9875\uFF0C\u4F4F\u5BBF\u663E\u793A\u5728\u5C55\u793A\u533A\uFF0C Hero \u8F6E\u64AD\u5C55\u793A\u5728\u9996\u9875\u6A2A\u5E45\u3002",
      itinerary_copy: "\u516C\u5F00\u884C\u7A0B\u9875\u9762\u7684\u9010\u65E5\u63CF\u8FF0\u3002\u4EE5\u9500\u552E\u4E3A\u76EE\u7684\u8FDB\u884C\u64B0\u5199\u3002\u4E0E\u5C55\u90E8\u6807\u7B7E\u76F8\u72EC\u7ACB \u2014 \u5C55\u90E8\u9A71\u52A8\u8FD0\u8425\u5DE5\u4F5C\u6D41\uFF0C\u81EA\u52A8\u751F\u6210\u5458\u5DE5\u5F85\u529E\u4E8B\u9879\u3002",
      linked_destinations_label: "\u5173\u8054\u76EE\u7684\u5730",
      linked_destinations: "\u5C06\u6B64\u884C\u7A0B\u4E0E\u76EE\u7684\u5730\u76EE\u5F55\u4E2D\u7684\u6761\u76EE\u5173\u8054\u3002\u5173\u8054\u7684\u76EE\u7684\u5730\u5728\u884C\u7A0B\u9875\u9762\u663E\u793A\u4E3A\u76F8\u5173\u76EE\u7684\u5730\u5757\u3002",
      linked_hotels_label: "\u5173\u8054\u9152\u5E97",
      linked_hotels: "\u5C06\u76EE\u5F55\u4E2D\u7684\u9152\u5E97\u4E0E\u4F4F\u5BBF\u665A\u6570\u5173\u8054\u3002\u7528\u4E8E\u884C\u7A0B\u9875\u9762\u7684\u4F4F\u5BBF\u90E8\u5206\u548C\u8FD0\u8425\u5DE5\u4F5C\u6D41\u3002",
      linked_libraries_label: "\u5173\u8054\u56FE\u5E93",
      linked_libraries: "\u5171\u4EAB\u7167\u7247\u5408\u96C6 \u2014 \u4F8B\u5982\u201C\u4E0B\u9F99\u6E7E\u7167\u7247\u201D\u3002\u5173\u8054\u56FE\u5E93\u540E\uFF0C\u65E0\u9700\u91CD\u590D\u4E0A\u4F20\u5373\u53EF\u5728\u753B\u5ECE\u548C\u5C01\u9762\u56FE\u9009\u62E9\u5668\u4E2D\u4F7F\u7528\u8FD9\u4E9B\u7167\u7247\u3002",
      stops_builder_title: "\u5C55\u90E8\u662F\u8FD0\u8425\u5DE5\u4F5C\u6D41\u7684\u6838\u5FC3\u3002",
      stops_builder: "\u6B64\u5904\u6DFB\u52A0\u7684\u6BCF\u4E2A\u5C55\u90E8\u90FD\u4F1A\u5728\u8FD0\u8425\u770B\u677F\u81EA\u52A8\u751F\u6210\u56E2\u961F\u5F85\u529E\u4E8B\u9879\u6E05\u5355 \u2014 \u5BFC\u6E38\u3001\u53F8\u673A\u3001\u9152\u5E97\u3001\u9910\u9A90\u3002\u5C55\u90E8\u8D8A\u5B8C\u6574\uFF0C\u81EA\u52A8\u751F\u6210\u7684\u4EFB\u52A1\u5217\u8868\u8D8A\u4E30\u5BCC\u3002",
      stops_builder_note: "\u6309\u987A\u5E8F\u6DFB\u52A0\u5C55\u90E8\uFF1A\u5230\u8FBE\u3001\u4F9D\u6B21\u5404\u76EE\u7684\u5730\u3001\u7136\u540E\u51FA\u53D1\u3002\u8FC7\u5883\u6216\u5F53\u5929\u5C55\u90E8\u8BBE\u665A\u6570=0\u3002",
      stop_nights: "\u56E2\u961F\u5728\u6B64\u76EE\u7684\u5730\u4F4F\u5BBF\u7684\u665A\u6570\u3002\u63A7\u5236\u8BE5\u5C55\u90E8\u5728\u884C\u7A0B\u4E2D\u5360\u7528\u7684\u5929\u6570\u3002\u8FC7\u5883\u6216\u51FA\u53D1\u5C55\u90E8\u8BBE0 \u2014 \u4E0D\u4F4F\u5BBF\uFF0C\u4E0D\u751F\u6210\u9152\u5E97\u4EFB\u52A1\u3002",
      stop_meals: "\u5207\u6362\u6B64\u5C55\u90E8\u5305\u542B\u7684\u9910\u9A90\uFF08B=\u65E9\u9910\uFF0CL=\u5348\u9910\uFF0CD=\u665A\u9910\uFF09\u3002\u751F\u6210\u9910\u9A90\u534F\u8C03\u4EFB\u52A1\u5E76\u663E\u793A\u5728\u5BA2\u6237\u884C\u7A0B\u8868\u4E2D\u3002",
      price_settings: "\u5C55\u793A\u8D27\u5E01\u662F\u5728\u7F51\u7AD9\u5411\u5BA2\u6237\u663E\u793A\u4EF7\u683C\u7684\u8D27\u5E01\uFF0C\u4E0E\u9884\u8BA2\u8D27\u5E01\u5206\u5F00\u3002\u6240\u6709\u4EF7\u683C\u884C\u5747\u4EE5\u9884\u8BA2\u8D27\u5E01\u5B58\u50A8 \u2014 \u5C55\u793A\u8D27\u5E01\u5728\u516C\u5F00\u9875\u9762\u8F6C\u6362\u663E\u793A\u3002",
      seasons: "\u51B3\u5B9A\u9002\u7528\u54EA\u4E00\u4EF7\u683C\u884C\u7684\u65E5\u671F\u8303\u56F4\u3002\u4F8B\uFF1A\u65FA\u5B63 12\u201322\u6708\uFF0C\u6DE1\u5B63 3\u201311\u6708\u3002\u7CFB\u7EDF\u81EA\u52A8\u5C06\u5BA2\u6237\u7684\u51FA\u884C\u65E5\u671F\u5339\u914D\u5230\u6B63\u786E\u65FA\u5B63\u3002",
      pax_bands: "\u8BBE\u5B9A\u4EBA\u5747\u4EF7\u683C\u7684\u56E2\u4F53\u89C4\u6A21\u6863\u4F4D\u3002\u56E2\u4F53\u8D8A\u5927\u901A\u5E38\u4EF7\u683C\u8D8A\u4F4E\u3002\u4F8B\uFF1A\u5355\u72EC (1\u20132\u4EBA)\uFF0C\u5C0F\u56E2 (3\u20138)\uFF0C\u56E2\u4F539+\u3002",
      segments: "\u4E0D\u540C\u670D\u52A1\u7EA7\u522B\u7684\u884C\u7A0B\u5E93\u5B58 \u2014 \u4F8B\uFF1A\u6807\u51C6\u4E0E\u8D35\u5BBE\u3002\u6BCF\u4E2A\u6863\u4F4D\u6709\u72EC\u7ACB\u4EF7\u683C\u8868\u4F46\u5171\u4EAB\u884C\u7A0B\u8868\u3002\u5982\u679C\u53EA\u6709\u4E00\u4E2A\u7B49\u7EA7\uFF0C\u4FDD\u6301\u9ED8\u8BA4\u6863\u4F4D\u5373\u53EF\u3002",
      tour_prices: "\u4EF7\u683C\u8868 \u2014 \u6BCF\u4E2A\u65FA\u5B63+\u6863\u4F4D+\u5BA2\u6237\u6570\u6863\u4F4D\u7EC4\u5408\u5BF9\u5E94\u4E00\u884C\u3002\u6BCF\u884C\u6309\u65C5\u884C\u8005\u7C7B\u578B\u5217\u51FA\u4EF7\u683C\uFF1A\u53CC\u4EBA\u95F4\u3001\u4E09\u4EBA\u95F4\u3001\u5355\u4EBA\u95F4\u3001\u5150\u7AE5\uFF08\u4E0E\u7236\u6BCD\u540C\u4F4F\uFF09\u3001\u5A74\u513F\u3002\u5F53\u5929\u6E38\u4EC5\u9002\u7528\u6210\u4EBA\u548C\u5150\u7AE5\u4EF7\u683C\u3002",
      pricing_definitions: "\u9884\u8BA2\u5C0F\u5DE5\u5177\u4EF7\u683C\u5408\u8BA1\u4E0B\u65B9\u663E\u793A\u7684\u201C\u7279\u522B\u63D0\u793A\u201D\u5757\u3002\u5728\u6B64\u5217\u51FA\u5305\u542B\u9879\u76EE\u3001\u5150\u7AE5\u5E74\u9F84\u6863\u4F4D\u4EE5\u53CA\u53D6\u6D88\u6216\u5B9A\u91D1\u653F\u7B56\u3002"
