      stops_builder_note: "\u5230\u7740\u3001\u5404\u76EE\u7684\u5730\u3001\u51FA\u767A\u306E\u9806\u306B\u30B9\u30C8\u30C3\u30D7\u3092\u8FFD\u52A0\u3002\u30C8\u30E9\u30F3\u30B8\u30C3\u30C8\u3084\u5F53\u65E5\u6C34\u305F\u308A\u306E\u30B9\u30C8\u30C3\u30D7\u306F\u6CCA\u6570=0\u3002",
      stop_nights: "\u30B0\u30EB\u30FC\u30D7\u304C\u3053\u306E\u76EE\u7684\u5730\u3067\u6CCA\u307E\u308B\u591C\u6570\u3002\u65C5\u7A0B\u8868\u3067\u3053\u306E\u30B9\u30C8\u30C3\u30D7\u304C\u5360\u3081\u308B\u65E5\u6570\u3092\u5236\u5FA1\u3002\u30C8\u30E9\u30F3\u30B8\u30C3\u30C8\u304A\u3088\u3073\u51FA\u767A\u30B9\u30C8\u30C3\u30D7\u306F0 \u2014 \u5BBF\u6CCA\u306A\u3057\u3001\u30DB\u30C6\u30EB\u30BF\u30B9\u30AF\u751F\u6210\u306A\u3057\u3002",
