    help: {
      tour_type_package_label: "\uB2E4\uC77C \uD328\uD0A4\uC9C0",
      tour_type_package_desc: "\uC5EC\uB7EC \uB0A0 \uC219\uBC15\uC774 \uC788\uB294 \uC5EC\uD589. \uC815\uB958\uC9C0(\uC790\uB3D9 \uD560 \uC77C \uBAA9\uB85D\uC6A9) \uBC0F \uBC29 \uC885\uB958\uBCC4 \uC644\uC804\uD55C \uC694\uAE08 \uC124\uC815\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.",
      tour_type_day_label: "\uB2F9\uC77C \uD22C\uC5B4",
      tour_type_day_desc: "\uAC19\uC740 \uB0A0 \uC2DC\uC791\uD558\uACE0 \uC885\uB8CC\uD569\uB2C8\uB2E4. \uBC29 \uAC00\uACA9 \uC5C6\uC74C \u2014 \uC131\uC778 \uBC0F \uC5B4\uB9B0\uC774 \uC778\uB2F9 \uAC00\uACA9\uB9CC \uD574\uB2F9\uD569\uB2C8\uB2E4.",
      metadata: "\uD575\uC2EC \uC2DC\uC2A4\uD15C \uD544\uB4DC. \uC81C\uBAA9\uACFC \uAE30\uAC04\uC740 \uBAA9\uB85D\uACFC \uAC80\uC0C9\uC5D0 \uD45C\uC2DC\uB429\uB2C8\uB2E4. \uC0C1\uD0DC\uB294 \uACE0\uAC1D \uBCF4\uC774\uAE30\uB97C \uC81C\uC5B4\uD569\uB2C8\uB2E4. \uBC88\uC5ED\uC774 \uC791\uB3D9\uD558\uB3C4\uB85D \uC5B8\uC5B4\uB97C \uC62C\uBC14\uB974\uAC8C \uC124\uC815\uD558\uC138\uC694.",
      content_data: "\uACE0\uAC1D\uC774 \uD22C\uC5B4 \uD398\uC774\uC9C0\uC5D0\uC11C \uBCF4\uB294 \uBAA8\uB4E0 \uAC83. \uD22C\uC5B4 \uC774\uB984\uC740 \uD070 \uD45C\uC81C, \uAE30\uBCF8 \uAC00\uACA9\uC740 \u2018\uBD80\uD130\u2019 \uAC00\uACA9, \uD558\uC774\uB77C\uC774\uD2B8\uB294 \uC544\uC774\uCF58 \uBCF4\uB808\uD2B8, \uD3EC\uD568/\uBBF8\uD3EC\uD568\uC740 \uCCB4\uD06C\uB9AC\uC2A4\uD2B8.",
      hero_image: "\uD22C\uC5B4 \uD398\uC774\uC9C0 \uC0C1\uB2E8\uC758 \uC804\uCCB4 \uD3ED \uBC30\uB108. \uC774\uBBF8\uC9C0 \uCD94\uAC00 \uBC84\uD2BC\uC73C\uB85C \uAC24\uB7EC\uB9AC\uC5D0\uC11C \uC120\uD0DD\uD558\uAC70\uB098 \uC5C5\uB85C\uB4DC\uD558\uC138\uC694. \uD788\uC5B4\uB85C \uC774\uBBF8\uC9C0\uB294 \uD56D\uC0C1 \uBA85\uC2DC\uC801\uC73C\uB85C \uC124\uC815\uB429\uB2C8\uB2E4.",
      gallery_images: "\uD22C\uC5B4 \uD398\uC774\uC9C0 \uAC64\uB7EC\uB9AC\uC758 \uC0AC\uC9C4 \uBAA8\uC74C. \uC774\uBBF8\uC9C0 \uCD94\uAC00 \u2014 \uAC01 \uC774\uBBF8\uC9C0\uB294 \uD788\uC5B4\uB85C\uB098 \uB2E4\uB978 \uD544\uB4DC\uB97C \uAC74\uB4DC\uB9AC\uC9C0 \uC54A\uACE0 \uBAA9\uB85D\uC5D0 \uCD94\uAC00\uB429\uB2C8\uB2E4.",
      destination: "\uD22C\uC5B4 \uD398\uC774\uC9C0\uC758 \uAD00\uAD11\uC9C0 \uCE74\uB4DC \u2014 \uC774\uB984\uACFC \uC0AC\uC9C4. \uC6F9\uC0AC\uC774\uD2B8 \uBAA9\uC801\uC9C0 \uD398\uC774\uC9C0\uC5D0\uB3C4 \uD45C\uC2DC\uD558\uB824\uBA74 \u2018\uBAA9\uC801\uC9C0\u2019\uB97C \uCCB4\uD06C\uD558\uC138\uC694.",
      accommodation: "\uD22C\uC5B4 \uD398\uC774\uC9C0\uC758 \uC228\uC18C \uC815\uBCF4 \u2014 \uC81C\uBAA9, \uC774\uBBF8\uC9C0, \uC9E7\uC740 \uC124\uBA85. \uC228\uC18C \uC2FC\uCF00\uC774\uC2A4\uC5D0 \uD3EC\uD568\uD558\uB824\uBA74 \u2018\uC228\uC18C\u2019\uB97C \uCCB4\uD06C\uD558\uC138\uC694.",
      site_placement: "\uC6F9\uC0AC\uC774\uD2B8\uC5D0\uC11C \uC774 \uD22C\uC5B4\uAC00 \uD45C\uC2DC\uB418\uB294 \uC704\uCE58\uB97C \uC81C\uC5B4\uD569\uB2C8\uB2E4. \uC8FC\uC694 \uD22C\uC5B4\uB294 \uC8FC\uC694 \uD589 \uD45C\uC2DC, \uBAA9\uC801\uC9C0\uB294 \uCE74\uD0C8\uB85C\uADF8 \uD398\uC774\uC9C0, \uC228\uC18C\uB294 \uC2DC\uC6A9\uC2DC\uB178\uC2DC\uC2A4, \uD788\uC5B4\uB85C \uC2A4\uD3EC\uD2B8\uB77C\uC774\uD2B8\uB294 \uBA54\uC778 \uBC30\uB108.",
      itinerary_copy: "\uACF5\uAC1C \uD22C\uC5B4 \uD398\uC774\uC9C0\uC758 \uC77C\uBCC4 \uC2A4\uD1A0\uB9AC. \uD310\uB9E4 \uBAA9\uC801\uC73C\uB85C \uC791\uC131\uD558\uC138\uC694. \uC815\uB958\uC9C0 \uD0ED\uACFC\uB294 \uBCC4\uB3C4 \u2014 \uC815\uB958\uC9C0\uB294 \uC6B4\uC601 \uC6CC\uD06C\uD50C\uB85C\uC6B0\uB97C \uC8FC\uB3C4\uD558\uACE0 \uC2A4\uD0DC\uD504 \uD560 \uC77C \uBAA9\uB85D\uC744 \uC790\uB3D9 \uC0DD\uC131\uD569\uB2C8\uB2E4.",
      linked_destinations_label: "\uC5F0\uACB0\uB41C \uBAA9\uC801\uC9C0",
      linked_destinations: "\uBAA9\uC801\uC9C0 \uCE74\uD0C8\uB85C\uADF8\uC640 \uC5F0\uACB0\uD558\uC138\uC694. \uC5F0\uACB0\uB41C \uBAA9\uC801\uC9C0\uB294 \uD22C\uC5B4 \uD398\uC774\uC9C0\uC5D0 \uC5F0\uAD00 \uBE14\uB85D\uC73C\uB85C \uD45C\uC2DC\uB429\uB2C8\uB2E4.",
      linked_hotels_label: "\uC5F0\uACB0\uB41C \uD638\uD154",
      linked_hotels: "\uCE74\uD0C8\uB85C\uADF8\uC5D0\uC11C \uD638\uD154\uC744 \uC228\uBC15 \uC218\uC640 \uD568\uAED8 \uC5F0\uACB0\uD558\uC138\uC694. \uD22C\uC5B4 \uD398\uC774\uC9C0\uC758 \uC228\uC18C \uC138\uC158\uACFC \uC6B4\uC601 \uC6CC\uD06C\uD50C\uB85C\uC6B0\uC5D0 \uC0AC\uC6A9\uB429\uB2C8\uB2E4.",
      linked_libraries_label: "\uC5F0\uACB0\uB41C \uC0AC\uC9C4 \uB77C\uC774\uBE0C\uB7EC\uB9AC",
      linked_libraries: "\uACF5\uC720 \uC0AC\uC9C4 \uCF5C\uB809\uC158 \u2014 \uC608: \u2018\uD558\uB871\uB9CC \uC0AC\uC9C4\u2019. \uB77C\uC774\uBE0C\uB7EC\uB9AC \uC5F0\uACB0 \uC2DC \uC911\uBCF5 \uC5C5\uB85C\uB4DC \uC5C6\uC774 \uAC24\uB7EC\uB9AC \uBC0F \uD788\uC5B4\uB85C \uC120\uD0DD\uC5D0\uC11C \uC0AC\uC9C4\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
      stops_builder_title: "\uC815\uB958\uC9C0\uB294 \uC6B4\uC601 \uC6CC\uD06C\uD50C\uB85C\uC6B0\uB97C \uC8FC\uB3C4\uD569\uB2C8\uB2E4.",
      stops_builder: "\uC774\uACF3\uC5D0 \uCD94\uAC00\uD55C \uAC01 \uC815\uB958\uC9C0\uB294 \uAC00\uC774\uB4DC, \uC6B4\uC804\uAE30\uC0AC, \uD638\uD154, \uC2DD\uC0AC \uB4F1 \uD300\uC758 \uD560 \uC77C \uBAA9\uB85D\uC744 \uC6B4\uC601 \uBCF4\uB4DC\uC5D0 \uC790\uB3D9 \uC0DD\uC131\uD569\uB2C8\uB2E4. \uC815\uB958\uC9C0\uAC00 \uC644\uC804\uD560\uC218\uB85D \uC790\uB3D9 \uC0DD\uC131 \uBAA9\uB85D\uC774 \uD48D\uBD80\uD574\uC9D1\uB2C8\uB2E4.",
      stops_builder_note: "\uC21C\uC11C\uB300\uB85C \uC815\uB958\uC9C0\uB97C \uCD94\uAC00\uD558\uC138\uC694: \uB3C4\uCC29, \uAC01 \uBAA9\uC801\uC9C0, \uC774\uD6C4 \uCD9C\uBC1C. \uACBD\uC720\uC9C0 \uB610\uB294 \uB2F9\uC77C \uC815\uB958\uC9C0\uB294 \uC228\uBC15 = 0.",
      stop_nights: "\uADF8\uB8F9\uC774 \uC774 \uBAA9\uC801\uC9C0\uC5D0\uC11C \uC790\uB294 \uBC24 \uC218. \uC77C\uC815\uD45C\uC5D0\uC11C \uC774 \uC815\uB958\uC9C0\uAC00 \uCC28\uC9C0\uD558\uB294 \uC77C\uC218\uB97C \uC81C\uC5B4\uD569\uB2C8\uB2E4. \uACBD\uC720\uC9C0 \uB610\uB294 \uCD9C\uBC1C\uC9C0\uB294 0 \u2014 \uC228\uBC15 \uC5C6\uC74C, \uD638\uD154 \uD560 \uC77C \uC5C6\uC74C.",
      stop_meals: "\uC774 \uC815\uB958\uC9C0\uC5D0\uC11C \uD3EC\uD568\uB41C \uC2DD\uC0AC\uB97C \uD1A0\uAE00\uD558\uC138\uC694 (B=\uC544\uCE68, L=\uC810\uC2EC, D=\uC800\uB141). \uC2DD\uC0AC \uC870\uC728 \uD560 \uC77C\uC744 \uC0DD\uC131\uD558\uACE0 \uACE0\uAC1D\uC6A9 \uC77C\uC815\uD45C\uC5D0 \uD45C\uC2DC\uB429\uB2C8\uB2E4.",
      price_settings: "\uD45C\uC2DC \uD1B5\uD654\uB294 \uC6F9\uC0AC\uC774\uD2B8\uC5D0\uC11C \uACE0\uAC1D\uC5D0\uAC8C \uBCF4\uC5EC\uC9C0\uB294 \uAC00\uACA9 \uD1B5\uD654\uC785\uB2C8\uB2E4. \uC608\uC57D \uD1B5\uD654\uC640 \uB2E4\uB985\uB2C8\uB2E4. \uBAA8\uB4E0 \uAC00\uACA9 \uD589\uC740 \uC608\uC57D \uD1B5\uD654\uB85C \uC800\uC7A5\uB429\uB2C8\uB2E4 \u2014 \uD45C\uC2DC \uD1B5\uD654\uB294 \uACF5\uAC1C \uD398\uC774\uC9C0\uC5D0\uC11C \uD658\uC0B0\uC73C\uB85C \uC801\uC6A9\uB429\uB2C8\uB2E4.",
      seasons: "\uC5B4\uB5A4 \uAC00\uACA9 \uD589\uC774 \uC801\uC6A9\uB418\uB294\uC9C0\uB97C \uACB0\uC815\uD558\uB294 \uB0A0\uC9DC \uBC94\uC704. \uC608: \uC131\uC218\uAE30 12\u2013\uC6D42\uC6D4, \uBE44\uC218\uAE30 3\u2013\uC6D411\uC6D4. \uC2DC\uC2A4\uD15C\uC774 \uACE0\uAC1D\uC758 \uC5EC\uD589 \uB0A0\uC9DC\uC5D0 \uC790\uB3D9\uC73C\uB85C \uB9DE\uB294 \uC2DC\uC98C\uC744 \uC120\uD0DD\uD569\uB2C8\uB2E4.",
      pax_bands: "\uC778\uB2F9 \uAC00\uACA9\uC744 \uC124\uC815\uD558\uB294 \uADF8\uB8F9 \uADDC\uBAA8 \uB2E8\uC704. \uD06C\uAC70\uB098 \uADF8\uB8F9\uC740 \uBCF4\uD1B5 \uB354 \uC800\uB834\uD55C \uC694\uAE08. \uC608: \uC194\uB85C (1\u20132\uBA85), \uC18C\uADF8\uB8F9 (3\u20138\uBA85), \uADF8\uB8F9 9+.",
      segments: "\uB2E4\uB978 \uC11C\uBE44\uC2A4 \uB808\uBCA8\uC758 \uD22C\uC5B4 \uBCC0\uD615 \u2014 \uC608: \uC2A4\uD0E0\uB2E4\uB4DC vs \uD504\uB9AC\uBBF8\uC5C4. \uAC01 \uC138\uADF8\uBA3C\uD2B8\uB294 \uB3C4\uC77C\uD55C \uC77C\uC815\uC744 \uACF5\uC720\uD558\uC9C0\uB9CC \uAC1C\uBCC4 \uAC00\uACA9 \uD45C\uAC00 \uC788\uC2B5\uB2C8\uB2E4.",
      tour_prices: "\uAC00\uACA9 \uD45C \u2014 \uC2DC\uC98C + \uC138\uADF8\uBA3C\uD2B8 + \uD329\uC2A4 \uB2E8\uC704 \uC870\uD569\uBCC4 \uD55C \uD589. \uC5EC\uD589\uC790 \uC720\uD615\uBCC4 \uAC00\uACA9: \uB354\uBE14\uB8F8, \uD2B8\uB9AC\uD50C, \uC2F1\uAE00, \uC5B4\uB9B0\uC774(\uBD80\uBAA8\uC640 \uC874\uC2E4), \uC720\uC544. \uB2F9\uC77C \uD22C\uC5B4\uB294 \uC131\uC778\uACFC \uC5B4\uB9B0\uC774\uB9CC.",
      pricing_definitions: "\uC608\uC57D \uC704\uC82F\uC758 \uCD1D\uC561 \uC544\uB798\uC5D0 \u2018\uC54C\uC544\uB450\uBA74 \uC88B\uC740 \uC815\uBCF4\u2019 \uBE14\uB85D\uC73C\uB85C \uD45C\uC2DC\uB418\uB294 \uB178\uD2B8. \uD3EC\uD568 \uC0AC\uD56D, \uC5B4\uB9B0\uC774 \uB098\uC774 \uAD6C\uAC04, \uCDE8\uC18C \uBC0F \uACC4\uC57D\uAE08 \uC815\uCC45\uC744 \uC791\uC131\uD558\uC138\uC694."
    }
