bookings.get("/orders", async (c) => {
  const tenantId2 = c.req.header("X-Tenant-ID")?.trim();
  if (!tenantId2) return c.json({ error: "X-Tenant-ID header is required." }, 400);
  const statusFilter = c.req.query("status");
  const limit = Math.min(Number(c.req.query("limit") ?? 50), 200);
  let sql = `SELECT * FROM booking_orders WHERE tenant_id = ?`;
  const binds = [tenantId2];
  if (statusFilter) {
    sql += ` AND status = ?`;
    binds.push(statusFilter.toUpperCase());
  }
  sql += ` ORDER BY created_at DESC LIMIT ?`;
  binds.push(limit);
  const { results } = await c.env.DB.prepare(sql).bind(...binds).all();
  return c.json({
    ok: true,
    count: results.length,
    orders: results.map(maskOrder)
  });
});
