  const headerMarkup = isLuxuryShell ? activeTheme.renderHeader?.({ site, homeSlug, menuItems, buildMenuHref, headerCtaHref: headerPrimaryHref, headerCtaLabel: headerPrimaryLabel, socialEntries, buildChannelHref, buildChannelLabel, buildSocialMonogram, logoMarkup, theme, systemCopy }) : `<header class="sticky top-0 z-30 border-b border-slate-200/70 bg-white/90 backdrop-blur"><div class="mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-4 py-4 sm:px-6"><div><p class="text-xs uppercase tracking-[0.24em] text-slate-500">${escapeHtml2(site.site_name || "Travel")}</p><p class="text-lg font-semibold text-slate-900">${escapeHtml2(title)}</p></div>${navMarkup}<a href="${escapeHtml2(headerPrimaryHref)}" class="rounded-full px-4 py-2 text-sm font-medium text-white" style="background:${escapeHtml2(primaryColor)}">${escapeHtml2(headerPrimaryLabel)}</a></div></header>`;
  const floatingBookNowMarkup = isLuxuryShell ? activeTheme.renderFloatingBookNow?.({ channels, buildChannelHref, buildChannelLabel, buildSocialMonogram, theme, systemCopy }) : "";
